const listCertificates = `-- name: ListCertificates :many
SELECT c.id, c.uuid, c.user_id, c.organization_id, c.brand_id, c.type_id, c.storage_key, c.sha256, c.issued_at, c.expires_at, c.status, c.verified_by_user_id, c.verified_by_org_id, c.verified_at, c.reject_reason, c.expiry_notice_sent_at, c.created_at, c.updated_at, u.name AS user_name, u.surname AS user_surname, u.uuid AS user_uuid,
       ct.uuid AS type_uuid, ct.name AS type_name,
       o.uuid AS organization_uuid, o.name AS organization_name
FROM certificates c
JOIN users u ON u.id = c.user_id
JOIN certificate_types ct ON ct.id = c.type_id
JOIN organizations o ON o.id = c.organization_id
WHERE c.brand_id = $1
  AND ($2::bigint[] IS NULL OR c.organization_id = ANY ($2::bigint[]))
  AND (COALESCE(cardinality($3::text[]), 0) = 0 OR c.status = ANY ($3::text[]))
  AND (COALESCE(cardinality($4::bigint[]), 0) = 0 OR c.type_id = ANY ($4::bigint[]))
  AND ($5::timestamptz IS NULL OR c.expires_at >= $5::timestamptz)
  AND ($6::timestamptz IS NULL OR c.expires_at < $6::timestamptz)
  AND (
    COALESCE(cardinality($7::uuid[]), 0) = 0
    OR c.organization_id IN (SELECT fo.id FROM organizations fo WHERE fo.uuid = ANY ($7::uuid[]))
  )
  AND (
    $8::text IS NULL
    OR (u.name || ' ' || u.surname) ILIKE '%' || $8::text || '%'
    OR u.email ILIKE '%' || $8::text || '%'
  )
ORDER BY
  CASE WHEN NOT $9::bool AND $10::text = 'expires_at' THEN c.expires_at END ASC NULLS LAST,
  CASE WHEN $9::bool AND $10::text = 'expires_at' THEN c.expires_at END DESC NULLS LAST,
  CASE WHEN NOT $9::bool THEN
    CASE $10::text
      WHEN 'status' THEN c.status::text
      WHEN 'user_name' THEN (u.name || ' ' || u.surname)::text
    END
  END ASC,
  CASE WHEN $9::bool THEN
    CASE $10::text
      WHEN 'status' THEN c.status::text
      WHEN 'user_name' THEN (u.name || ' ' || u.surname)::text
    END
  END DESC,
  CASE WHEN NOT $9::bool THEN
    CASE $10::text WHEN 'issued_at' THEN c.issued_at WHEN 'created_at' THEN c.created_at END
  END ASC,
  CASE WHEN $9::bool THEN
    CASE $10::text WHEN 'issued_at' THEN c.issued_at WHEN 'created_at' THEN c.created_at END
  END DESC,
  CASE WHEN $9::bool THEN c.id END DESC,
  c.id ASC
LIMIT $12 OFFSET $11
`

